"""A fake AI model client for offline tests. Do not edit this file.

It is NOT a live or paid AI call: it returns the scripted answers it was given, in order,
and remembers every prompt it received so a test can check what would have been sent.
"""


class ModelError(Exception):
    """The model call failed (for example a timeout or a refused request)."""


class FakeModelClient:
    def __init__(self, answers):
        """`answers` is a list; each item is a response string, or an exception to raise."""
        self._answers = list(answers)
        self.prompts = []

    def complete(self, prompt):
        """Return the next scripted answer for `prompt` (or raise it when it is an exception)."""
        self.prompts.append(prompt)
        if not self._answers:
            raise ModelError("the fake client has no answers left")
        answer = self._answers.pop(0)
        if isinstance(answer, Exception):
            raise answer
        return answer
